import { test, expect } from '@playwright/test';

test.describe('Sauce Demo Mobile Responsive', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport before navigating
    await page.setViewportSize({ width: 375, height: 812 });
    await page.goto('https://www.saucedemo.com');
  });

  test('should display login page on mobile viewport', async ({ page }) => {
    // Verify we're on the login page
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();
  });

  test('should login successfully and display inventory page on mobile', async ({ page }) => {
    // Fill in login credentials
    const usernameInput = page.getByLabel(/username/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Wait for navigation and verify inventory page is displayed
    await page.waitForURL('**/inventory.html');
    const inventoryContainer = page.locator('[data-test="inventory-container"]');
    await expect(inventoryContainer).toBeVisible();
  });

  test('should show burger menu button and open side menu on mobile', async ({ page }) => {
    // Login first
    const usernameInput = page.getByLabel(/username/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Wait for inventory page to load
    await page.waitForURL('**/inventory.html');

    // Verify burger menu button is visible
    const burgerMenuButton = page.locator('#react-burger-menu-btn');
    await expect(burgerMenuButton).toBeVisible();

    // Click the burger menu button
    await burgerMenuButton.click();

    // Verify the side menu container is visible
    const sideMenuContainer = page.locator('.bm-menu');
    await expect(sideMenuContainer).toBeVisible();

    // Verify logout link is visible inside the menu
    const logoutLink = page.locator('#logout_sidebar_link');
    await expect(logoutLink).toBeVisible();
  });

  test('should be able to logout from side menu on mobile', async ({ page }) => {
    // Login first
    const usernameInput = page.getByLabel(/username/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Wait for inventory page to load
    await page.waitForURL('**/inventory.html');

    // Open the burger menu
    const burgerMenuButton = page.locator('#react-burger-menu-btn');
    await burgerMenuButton.click();

    // Click logout link
    const logoutLink = page.locator('#logout_sidebar_link');
    await logoutLink.click();

    // Verify we're back on the login page
    await page.waitForURL('**/');
    const loginPageButton = page.getByRole('button', { name: /login/i });
    await expect(loginPageButton).toBeVisible();
  });
});
